#include <iostream>
#include <memory>
#include <string>
#include <vector>

struct Entity
{
    std::string name;
    int hp;
    Entity(std::string name, int hp) : name(name), hp(hp) {}
    ~Entity() { std::cout << "  (" << name << " deleted)\n"; }
};

void adopt(std::vector<std::unique_ptr<Entity>>& world, std::unique_ptr<Entity> e)
{
    world.push_back(std::move(e));          // ownership: caller -> function -> vector
}

int main()
{
    std::vector<std::unique_ptr<Entity>> world;
    world.push_back(std::make_unique<Entity>("Goblin", 30));

    auto boss = std::make_unique<Entity>("Troll", 200);
    adopt(world, std::move(boss));
    std::cout << "boss is " << (boss ? "still here" : "empty now") << "\n";

    for (auto& e : world) e->hp -= 10;
    std::cout << world[1]->name << " " << world[1]->hp << "\n";

    std::cout << "erasing the goblin\n";
    world.erase(world.begin());
    std::cout << "end of main\n";
    return 0;                                // the Troll is deleted here
}

