#include <memory>
#include <string>

struct Pickup
{
    inline static int alive = 0;
    std::string name;
    int value;
    Pickup(std::string name, int value) : name(name), value(value) { alive++; }
    ~Pickup() { alive--; }
};

std::unique_ptr<Pickup> makePickup(const std::string& name, int value)
{
    if (value <= 0) return nullptr;
    return std::make_unique<Pickup>(name, value);
}

// takes ownership of both; the loser is destroyed when this function ends
std::unique_ptr<Pickup> better(std::unique_ptr<Pickup> a, std::unique_ptr<Pickup> b)
{
    if (!a) return b;
    if (!b) return a;
    if (b->value > a->value) return b;
    return a;
}

