exercises.solution:
#include <memory>
#include <string>

struct Pickup
{
    inline static int alive = 0;
    std::string name;
    int value;
    Pickup(std::string name, int value) : name(name), value(value) { alive++; }
    ~Pickup() { alive--; }
};
#include <vector>

class Inventory
{
public:
    void add(std::unique_ptr<Pickup> item)
    {
        if (item) items.push_back(std::move(item));   // the vector owns it now
    }
    int size() const { return items.size(); }
    int totalValue() const
    {
        int total = 0;
        for (const auto& p : items) total += p->value;
        return total;
    }
    std::unique_ptr<Pickup> take(const std::string& name)
    {
        for (size_t i = 0; i < items.size(); i++) {
            if (items[i]->name == name) {
                auto out = std::move(items[i]);   // ownership leaves the vector
                items.erase(items.begin() + i);   // remove the now-empty slot
                return out;
            }
        }
        return nullptr;
    }
private:
    std::vector<std::unique_ptr<Pickup>> items;
};

