#include <memory>
#include <string>
#include <vector>

struct Entity
{
    inline static int alive = 0;
    std::string name;
    int hp;
    Entity(std::string name, int hp) : name(name), hp(hp) { alive++; }
    ~Entity() { alive--; }
};
#include <algorithm>

class World
{
public:
    Entity* spawn(const std::string& name, int hp)
    {
        entities.push_back(std::make_unique<Entity>(name, hp));
        return entities.back().get();      // a look-only pointer; the world still owns it
    }
    void damageAll(int amount)
    {
        for (auto& e : entities) e->hp -= amount;
    }
    int removeDead()
    {
        auto firstDead = std::remove_if(entities.begin(), entities.end(),
                                        [](const std::unique_ptr<Entity>& e) { return e->hp <= 0; });
        int removed = entities.end() - firstDead;
        entities.erase(firstDead, entities.end());   // the dead Entities are deleted here
        return removed;
    }
    int count() const { return entities.size(); }
    Entity* find(const std::string& name)
    {
        for (auto& e : entities)
            if (e->name == name) return e.get();
        return nullptr;
    }
private:
    std::vector<std::unique_ptr<Entity>> entities;
};
